def solve(coins, amount):
    """Return the fewest number of coins needed to make up the given amount.
    Unlimited supply of each coin value in `coins`. Return -1 if impossible.
    Uses DP with O(amount * len(coins)) time.
    """
    # Edge case
    if amount < 0:
        return -1
    # DP array where dp[i] = min coins to make i, init INF
    INF = amount + 1  # larger than any possible number of coins
    dp = [INF] * (amount + 1)
    dp[0] = 0
    for a in range(1, amount + 1):
        for c in coins:
            if c <= a:
                # if we can use coin c
                if dp[a - c] + 1 < dp[a]:
                    dp[a] = dp[a - c] + 1
    return dp[amount] if dp[amount] != INF else -1

