def solve(grid):
    # Count islands of 1s using DFS; handles empty grid and irregular row lengths.
    if not grid:
        return 0
    rows = len(grid)
    # Determine column count per row; we will use visited dict of (r,c)
    visited = set()
    def dfs(r, c):
        stack = [(r, c)]
        visited.add((r, c))
        while stack:
            x, y = stack.pop()
            for dx, dy in ((1,0),(-1,0),(0,1),(0,-1)):
                nx, ny = x + dx, y + dy
                if 0 <= nx < rows:
                    # check column bounds for that row
                    if 0 <= ny < len(grid[nx]) and (nx, ny) not in visited and grid[nx][ny] == 1:
                        visited.add((nx, ny))
                        stack.append((nx, ny))
    count = 0
    for i in range(rows):
        for j in range(len(grid[i])):
            if grid[i][j] == 1 and (i, j) not in visited:
                dfs(i, j)
                count += 1
    return count

