    """Return the number of islands in a possibly jagged grid.
    An island is a group of cells with value 1 connected vertically or horizontally.
    The grid may have rows of different lengths.
    """
    if not grid:
        return 0
    visited = set()
    rows = len(grid)
    def dfs(r, c):
        stack = [(r, c)]
        while stack:
            x, y = stack.pop()
            if (x, y) in visited:
                continue
            # bounds check for jagged rows
            if x < 0 or x >= rows:
                continue
            if y < 0 or y >= len(grid[x]):
                continue
            if grid[x][y] != 1:
                continue
            visited.add((x, y))
            # neighbors
            stack.append((x-1, y))
            stack.append((x+1, y))
            stack.append((x, y-1))
            stack.append((x, y+1))
    islands = 0
    for i in range(rows):
        for j in range(len(grid[i])):
            if grid[i][j] == 1 and (i, j) not in visited:
                islands += 1
                dfs(i, j)
    return islands
