def solve(nums):
    """Return the length of the longest strictly increasing subsequence.
    Uses patience sorting with binary search for O(n log n).
    """
    import bisect
    tails = []
    for x in nums:
        # find index to replace in tails
        i = bisect.bisect_left(tails, x)
        if i == len(tails):
            tails.append(x)
        else:
            tails[i] = x
    return len(tails)

