def solve(s: str) -> int:
    """Return the length of the longest substring without repeating characters.
    Sliding window algorithm with a dictionary storing the most recent index of each character.
    """
    last = {}
    start = 0
    best = 0
    for i, ch in enumerate(s):
        if ch in last and last[ch] >= start:
            start = last[ch] + 1
        last[ch] = i
        cur_len = i - start + 1
        if cur_len > best:
            best = cur_len
    return best

