            if visited[i][j] or grid[i][j]!=1:
                continue
            visited[i][j]=True
            stack.extend([(i-1,j),(i+1,j),(i,j-1),(i,j+1)])
    count=0
    for i in range(rows):
        for j in range(cols):
            if not visited[i][j] and grid[i][j]==1:
                count+=1
                dfs(i,j)
    return count

def solve(grid):
    """Count islands of 1s in a possibly jagged grid.
    The grid may have rows of different lengths; cells outside a row's length are ignored.
    Connectivity is 4-directional (up, down, left, right).
    """
    if not grid:
        return 0
    rows = len(grid)
    # visited set of (r,c) tuples for cells that are 1 and have been processed
    visited = set()
    def get_cell(r, c):
        if 0 <= r < rows and 0 <= c < len(grid[r]):
            return grid[r][c]
        return None
    def dfs(r, c):
        stack = [(r, c)]
        while stack:
            i, j = stack.pop()
            if (i, j) in visited:
                continue
            val = get_cell(i, j)
            if val != 1:
                continue
            visited.add((i, j))
            # explore 4 neighbours
            stack.append((i - 1, j))
            stack.append((i + 1, j))
            stack.append((i, j - 1))
            stack.append((i, j + 1))
    count = 0
    for i in range(rows):
        for j in range(len(grid[i])):
            if get_cell(i, j) == 1 and (i, j) not in visited:
                count += 1
                dfs(i, j)
    return count

